<?php declare(strict_types=1); use PHPUnit\Framework\TestCase;
final class P0EtsyOrderIntakeBindingStateContractTest extends TestCase {
 public function testPodResolutionRequiresExactListingBinding():void{$s=(string)file_get_contents(dirname(__DIR__,2).'/includes/Orders/ApprovedPodMappingResolver.php');self::assertStringContainsString('resolve(int $listingId,int $productVersionId,string $environment)',$s);self::assertStringContainsString('Tables::listing_pod_bindings()',$s);self::assertStringContainsString('b.listing_id=%d',$s);self::assertStringContainsString("b.readiness_hash REGEXP '^[a-f0-9]{64}$'",$s);}
 public function testPaidWebhookPersistsValidatedOrReviewRequiredState():void{$s=(string)file_get_contents(dirname(__DIR__,2).'/includes/Listings/EtsyOrderWebhookLifecycle.php');self::assertStringContainsString("\$targetState=\$reviewRequired?'REVIEW_REQUIRED':'VALIDATED'",$s);self::assertStringContainsString("\$this->orders->transition('order',(int)\$order['id'],\$targetState)",$s);self::assertStringContainsString("'persisted_order_state'",$s);self::assertStringNotContainsString("ApprovedPodMappingResolver::resolve(\$productVersionId,'production')",$s);}
}
